+// Scalar fallback for remainder tiles (mr < 4 or nr < 4)
+static inline void micro_kernel_scalar(int kb, int mr, int nr, const float* A, int lda, const float* B, int ldb, float* C, int ldc) {
+    for (int i = 0; i < mr; ++i) {
+        for (int j = 0; j < nr; ++j) {
+            float sum = C[i * ldc + j];
+            for (int k = 0; k < kb; ++k) {
+                sum += A[k * lda + i] * B[k * ldb + j];
+            }
+            C[i * ldc + j] = sum;
+        }
+    }
+}
